const assert = require('assert'), fs = require('fs'), os = require('os'), path = require('path');
const { uploaded } = require('../hooks/mem');
const outbox = fs.mkdtempSync(path.join(os.tmpdir(), 'ob-'));
fs.writeFileSync(path.join(outbox, '20261127T1000-error-handling.md'), 'x');
uploaded({ tool_input: { filename: '20261127T1000-error-handling.md' }, tool_response: 'File uploaded (1 bytes).\nwebUrl: https://x/20261127T1000-error-handling.md' }, outbox);
assert.ok(!fs.existsSync(path.join(outbox, '20261127T1000-error-handling.md')), 'a successful upload must leave the outbox');
